import { AppText as Text } from '@makanza/mobile-ui';
import { useCallback, useEffect, useMemo, useState } from 'react';
import { ActivityIndicator, Modal, Pressable, ScrollView, StyleSheet, View } from 'react-native';
import { Ionicons } from '../components/AppIcon';
import FormField from '../components/FormField';
import PrimaryButton from '../components/PrimaryButton';
import type { AppColors } from '../theme/colors';
import { api } from '../services/api';
import { formatMoney } from '../utils/format';

type Bank={name:string;code:string};
type WalletTransaction={id:string;type:string;direction:string;status:string;amountMinor:number;balanceAfter:number;reference:string;orderId:string|null;createdAt:string};
type VendorWallet={vendorStatus:string;balanceMinor:number;currency:string;status:string;dva:{accountNumber:string|null;accountName:string|null;bankName:string|null;status:string};payoutAccount:{accountLast4:string|null;accountName:string|null;bankName:string|null;bankCode:string|null;status:string};transactions:WalletTransaction[]};

export default function VendorWalletScreen({token,colors:c}:{token:string;colors:AppColors}){
  const s=styles(c);const [wallet,setWallet]=useState<VendorWallet|null>(null);const [loading,setLoading]=useState(true);const [error,setError]=useState('');const [notice,setNotice]=useState('');const [visible,setVisible]=useState(true);
  const [banks,setBanks]=useState<Bank[]>([]);const [payoutModal,setPayoutModal]=useState(false);const [bankModal,setBankModal]=useState(false);const [bankLoading,setBankLoading]=useState(false);const [bank,setBank]=useState<Bank|null>(null);const [accountNumber,setAccountNumber]=useState('');const [accountBusy,setAccountBusy]=useState(false);const [withdrawModal,setWithdrawModal]=useState(false);const [withdrawAmount,setWithdrawAmount]=useState('');const [withdrawBusy,setWithdrawBusy]=useState(false);

  const load=useCallback(async(quiet=false)=>{if(!quiet)setLoading(true);setError('');try{setWallet(await api.get<VendorWallet>('/vendor/wallet',token));}catch(e){setError(e instanceof Error?e.message:'Could not load your vendor wallet.');}finally{if(!quiet)setLoading(false);}},[token]);
  useEffect(()=>{void load();},[load]);
  useEffect(()=>{if(wallet?.dva.status!=='PENDING')return;const timer=setInterval(()=>void load(true),8000);return()=>clearInterval(timer);},[wallet?.dva.status,load]);
  useEffect(()=>{if(wallet?.payoutAccount.bankCode&&wallet.payoutAccount.bankName)setBank({code:wallet.payoutAccount.bankCode,name:wallet.payoutAccount.bankName});},[wallet?.payoutAccount.bankCode,wallet?.payoutAccount.bankName]);

  const openBanks=async()=>{setBankModal(true);if(banks.length)return;setBankLoading(true);try{setBanks(await api.get<Bank[]>('/vendor/wallet/banks',token));}catch(e){setError(e instanceof Error?e.message:'Could not load supported banks.');setBankModal(false);}finally{setBankLoading(false);}};
  const savePayoutAccount=async()=>{if(!bank||!/^\d{10}$/.test(accountNumber)){setError('Choose a bank and enter its 10 digit NUBAN account number.');return;}setAccountBusy(true);setError('');setNotice('');try{const saved=await api.put<{accountLast4:string;accountName:string;bankName:string;bankCode:string;status:string}>('/vendor/wallet/payout-account',{accountNumber,bankCode:bank.code},token);setNotice('Verified account: '+saved.accountName+' - '+saved.bankName+'.');setAccountNumber('');setPayoutModal(false);setBankModal(false);await load(true);}catch(e){setError(e instanceof Error?e.message:'Could not verify this bank account.');}finally{setAccountBusy(false);}};
  const withdraw=async()=>{const amountMinor=Math.round(Number(withdrawAmount)*100);if(!Number.isSafeInteger(amountMinor)||amountMinor<10000){setError('Enter a valid withdrawal amount of at least NGN 100.');return;}if(!wallet||amountMinor>wallet.balanceMinor){setError('The withdrawal amount is greater than your available balance.');return;}setWithdrawBusy(true);setError('');setNotice('');try{const result=await api.post<{status:string;reference:string;balanceMinor:number}>('/vendor/wallet/withdraw',{amountMinor,idempotencyKey:makeUuid()},token);setNotice(result.status==='SUCCEEDED'?'Your withdrawal was sent.':'Your withdrawal is processing. Reference '+result.reference.slice(-8)+'.');setWithdrawAmount('');setWithdrawModal(false);await load(true);}catch(e){setError(e instanceof Error?e.message:'Could not start this withdrawal.');await load(true);}finally{setWithdrawBusy(false);}};

  const accountReady=wallet?.payoutAccount.status==='VERIFIED';const canWithdraw=wallet?.vendorStatus==='APPROVED';
  const history=useMemo(()=>wallet?.transactions??[],[wallet?.transactions]);
  return <View style={s.screen}><View style={s.fixedHeader}><View style={s.headingRow}><View><Text style={s.kicker}>STORE FINANCES</Text><Text style={s.title}>Wallet</Text><Text style={s.subtitle}>Your earnings, deposits, and payouts.</Text></View><Pressable accessibilityRole="button" accessibilityLabel="Refresh wallet" onPress={()=>void load()} style={s.refresh}><Ionicons name="refresh-outline" size={21} color={c.green}/></Pressable></View></View><ScrollView contentContainerStyle={s.page}>
    {error?<View accessibilityRole="alert" style={s.errorBox}><Text style={s.error}>{error}</Text></View>:null}
    {notice?<View style={s.notice}><Text style={s.noticeText}>{notice}</Text><Pressable accessibilityRole="button" accessibilityLabel="Dismiss message" onPress={()=>setNotice('')}><Ionicons name="close" size={19} color={c.green}/></Pressable></View>:null}
    {loading&&!wallet?<ActivityIndicator style={{margin:28}} color={c.green}/>:wallet&&<>
      <View style={s.balanceCard}><View style={s.balanceTop}><View style={s.walletMark}><Ionicons name="wallet-outline" size={22} color="#e5efdc"/></View><Text style={s.balanceCaption}>AVAILABLE BALANCE</Text><Pressable accessibilityRole="button" accessibilityLabel={visible?'Hide balance':'Show balance'} onPress={()=>setVisible(v=>!v)}><Ionicons name={visible?'eye-outline':'eye-off-outline'} size={22} color="white"/></Pressable></View><Text style={s.balance}>{visible?formatMoney(wallet.balanceMinor):'••••••••'}</Text><Text style={s.balanceNote}>Vendor wallet · NGN</Text><View style={s.balanceFoot}><Text style={s.balanceFootText}>Earnings are added after an order is delivered.</Text><Ionicons name="trending-up-outline" size={19} color="#d8e5df"/></View></View>

      <View style={s.card}><View style={s.sectionTop}><View style={s.sectionIcon}><Ionicons name="business-outline" size={20} color={c.green}/></View><View style={s.flex}><Text style={s.sectionTitle}>Paystack deposit account</Text><Text style={s.copy}>Automatic Titan virtual account for your wallet.</Text></View><View style={[s.statusPill,wallet.dva.status==='ACTIVE'?s.statusGood:s.statusWait]}><Text style={s.statusText}>{wallet.dva.status==='ACTIVE'?'Ready':wallet.dva.status==='FAILED'?'Retry':'Setting up'}</Text></View></View>{wallet.dva.accountNumber?<View style={s.accountNumber}><Text style={s.accountLabel}>{wallet.dva.bankName??'TITAN PAYSTACK'}</Text><Text selectable style={s.number}>{wallet.dva.accountNumber}</Text><Text style={s.copy}>{wallet.dva.accountName??'Smile vendor wallet'}</Text></View>:<Text style={s.copyStrong}>{wallet.dva.status==='FAILED'?'Your Paystack account could not be created. Retry setup below.':'Paystack is setting up your dedicated account. This screen will update automatically.'}</Text>}{wallet.dva.status!=='ACTIVE'&&<PrimaryButton title={wallet.dva.status==='FAILED'?'Retry account setup':'Check account status'} secondary onPress={()=>void api.post('/wallet/dva/retry',{},token).then(()=>load(true)).catch(e=>setError(e instanceof Error?e.message:'Could not retry account setup.'))} style={s.button}/>}</View>

      <View style={s.card}><View style={s.sectionTop}><View style={s.sectionIcon}><Ionicons name="card-outline" size={20} color={c.green}/></View><View style={s.flex}><Text style={s.sectionTitle}>Withdrawal account</Text><Text style={s.copy}>{accountReady?wallet.payoutAccount.bankName+' - ending '+wallet.payoutAccount.accountLast4:'Add a Nigerian bank account to withdraw.'}</Text></View><Pressable accessibilityRole="button" accessibilityLabel={accountReady?'Edit withdrawal account':'Set up withdrawal account'} onPress={()=>{setError('');setBankModal(false);setPayoutModal(true);}} style={s.cardAction}><Ionicons name={accountReady?'create-outline':'add'} size={20} color={c.green}/></Pressable></View>{accountReady&&<Text style={s.verifiedName}>{wallet.payoutAccount.accountName}</Text>}</View>

      <View style={s.card}><View style={s.sectionTop}><View style={s.sectionIcon}><Ionicons name="wallet-outline" size={20} color={c.green}/></View><View style={s.flex}><Text style={s.sectionTitle}>Withdraw funds</Text><Text style={s.copy}>Send money to your verified bank account.</Text></View><Pressable accessibilityRole="button" accessibilityLabel="Withdraw funds" onPress={()=>{setError('');setWithdrawModal(true);}} style={s.cardAction}><Ionicons name="arrow-forward" size={20} color={c.green}/></Pressable></View>{!canWithdraw?<Text style={s.hint}>Withdrawals unlock after your store is approved.</Text>:!accountReady&&<Text style={s.hint}>Verify your withdrawal account first.</Text>}</View>

      <View style={s.historyHeading}><View><Text style={s.sectionTitle}>Wallet activity</Text><Text style={s.copy}>Earnings and withdrawals</Text></View><Text style={s.historyCount}>{history.length} recent</Text></View>
      {history.length?history.map(row=><TransactionRow key={row.id} row={row} colors={c}/>):<View style={s.empty}><View style={[s.emptyIcon,{width:56,height:56,borderRadius:0}]}><Ionicons name="receipt-outline" size={27} color={c.green}/></View><Text style={s.emptyTitle}>Your wallet is quiet</Text><Text style={[s.copy,{textAlign:'center',marginTop:4}]}>No activity yet. Delivered order earnings and withdrawals will appear here.</Text></View>}
    </>}
  </ScrollView>
  <Modal visible={payoutModal} transparent animationType="slide" onRequestClose={()=>{setPayoutModal(false);setBankModal(false);}}><View style={s.modalBackdrop}><View style={s.modal}><View style={s.modalHead}><View><Text style={s.modalTitle}>{bankModal?'Choose a bank':accountReady?'Update withdrawal account':'Set up withdrawal account'}</Text><Text style={s.copy}>{bankModal?'Nigerian banks supported by Paystack':'Verify a Nigerian bank account for payouts.'}</Text></View><Pressable accessibilityRole="button" accessibilityLabel={bankModal?'Back to withdrawal account':'Close withdrawal account setup'} onPress={()=>bankModal?setBankModal(false):setPayoutModal(false)}><Ionicons name={bankModal?'chevron-back':'close'} size={24} color={c.ink}/></Pressable></View>{bankModal?(bankLoading?<ActivityIndicator style={{margin:28}} color={c.green}/>:banks.length?<ScrollView style={{maxHeight:390}}>{banks.map(item=><Pressable key={item.code} accessibilityRole="button" onPress={()=>{setBank(item);setBankModal(false);}} style={s.bankOption}><Text style={s.bankName}>{item.name}</Text>{bank?.code===item.code&&<Ionicons name="checkmark-circle" size={20} color={c.green}/>}</Pressable>)}</ScrollView>:<View style={s.empty}><View style={[s.emptyIcon,{width:56,height:56,borderRadius:0}]}><Ionicons name="business-outline" size={27} color={c.green}/></View><Text style={s.emptyTitle}>No banks to show</Text><Text style={[s.copy,{textAlign:'center'}]}>Refresh and try loading the supported banks again.</Text></View>):<ScrollView keyboardShouldPersistTaps="handled" contentContainerStyle={{paddingBottom:8}}><Pressable accessibilityRole="button" onPress={()=>void openBanks()} style={s.selectBank}><Text style={bank?s.selectBankValue:s.selectBankPlaceholder}>{bank?.name??wallet?.payoutAccount.bankName??'Choose your bank'}</Text><Ionicons name="chevron-down" size={19} color={c.green}/></Pressable><FormField label="10 digit account number" value={accountNumber} onChangeText={value=>setAccountNumber(value.replace(/\D/g,'').slice(0,10))} placeholder={accountReady?'Enter the new account number':'Enter NUBAN'} keyboardType="number-pad" maxLength={10} dark={c.isDark}/>{error?<Text style={s.error}>{error}</Text>:null}<PrimaryButton title={accountBusy?'Verifying account...':accountReady?'Verify & update bank':'Verify & save bank'} onPress={()=>void savePayoutAccount()} disabled={accountBusy||bankLoading} style={s.button}/></ScrollView>}</View></View></Modal>
  <Modal visible={withdrawModal} transparent animationType="slide" onRequestClose={()=>setWithdrawModal(false)}><View style={s.modalBackdrop}><View style={s.modal}><View style={s.modalHead}><View><Text style={s.modalTitle}>Withdraw funds</Text><Text style={s.copy}>Available balance: {formatMoney(wallet?.balanceMinor??0)}</Text></View><Pressable accessibilityRole="button" accessibilityLabel="Close withdrawal" onPress={()=>setWithdrawModal(false)}><Ionicons name="close" size={24} color={c.ink}/></Pressable></View><ScrollView keyboardShouldPersistTaps="handled" contentContainerStyle={{paddingBottom:8}}>{wallet?.payoutAccount.status==='VERIFIED'&&<Text style={s.copyStrong}>{wallet.payoutAccount.bankName} - account ending {wallet.payoutAccount.accountLast4}</Text>}<FormField label="Amount" value={withdrawAmount} onChangeText={setWithdrawAmount} placeholder="e.g. 5000" keyboardType="decimal-pad" dark={c.isDark}/>{!canWithdraw?<Text style={s.hint}>Withdrawals unlock after your store is approved.</Text>:!accountReady&&<Text style={s.hint}>Set up and verify your withdrawal account first.</Text>}{error?<Text style={s.error}>{error}</Text>:null}<PrimaryButton title={withdrawBusy?'Requesting payout...':'Withdraw to bank'} onPress={()=>void withdraw()} disabled={!canWithdraw||!accountReady||withdrawBusy||(wallet?.balanceMinor??0)<10000} style={s.button}/></ScrollView></View></View></Modal>
  </View>;
}

function TransactionRow({row,colors:c}:{row:WalletTransaction;colors:AppColors}){const s=styles(c);const earning=row.direction==='CREDIT';const title=row.type==='ORDER_EARNING'?'Order earning':row.type==='WITHDRAWAL'?'Bank withdrawal':row.type==='WITHDRAWAL_REVERSAL'?'Withdrawal returned':row.type.replaceAll('_',' ').toLowerCase();return <View style={s.transaction}><View style={[s.txIcon,earning?s.txIn:s.txOut]}><Ionicons name={earning?'arrow-down-outline':'arrow-up-outline'} size={20} color={earning?'#28865b':'#a44232'}/></View><View style={s.txCopy}><Text style={s.txTitle}>{title}</Text><Text style={s.copy}>{row.orderId?`Order ${row.orderId.slice(-8)}`:new Date(row.createdAt).toLocaleDateString()}</Text><Text style={s.txStatus}>{row.status.toLowerCase()}</Text></View><Text style={[s.txAmount,!earning&&s.txDebit]}>{earning?'+':'−'}{formatMoney(row.amountMinor)}</Text></View>}

function makeUuid(){return'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g,letter=>{const value=Math.floor(Math.random()*16);return(letter==='x'?value:(value&3)|8).toString(16);});}

const styles=(c:AppColors)=>StyleSheet.create({screen:{flex:1,backgroundColor:c.paper},fixedHeader:{paddingHorizontal:18,paddingTop:14,backgroundColor:c.paper},page:{paddingHorizontal:18,paddingTop:5,paddingBottom:32},headingRow:{flexDirection:'row',alignItems:'center',justifyContent:'space-between',marginBottom:15},kicker:{fontSize:10,fontWeight:'900',letterSpacing:1.1,color:c.green},title:{fontSize:30,fontWeight:'900',letterSpacing:-.6,color:c.ink,marginTop:4},subtitle:{fontSize:12,color:c.muted,marginTop:2},refresh:{width:40,height:40,borderRadius:0,backgroundColor:c.cream,alignItems:'center',justifyContent:'center'},balanceCard:{padding:18,borderRadius:0,backgroundColor:c.green,overflow:'hidden',marginBottom:12},balanceTop:{flexDirection:'row',alignItems:'center',gap:9},walletMark:{width:35,height:35,borderRadius:0,alignItems:'center',justifyContent:'center',backgroundColor:'rgba(255,255,255,.14)'},balanceCaption:{flex:1,fontSize:10,fontWeight:'900',letterSpacing:1,color:'#e5efdc'},balance:{fontSize:34,fontWeight:'900',letterSpacing:-.5,color:'white',marginTop:14},balanceNote:{fontSize:11,color:'#e5efdc',marginTop:2},balanceFoot:{flexDirection:'row',alignItems:'center',justifyContent:'space-between',paddingTop:12,marginTop:13,borderTopWidth:1,borderTopColor:'rgba(255,255,255,.18)'},balanceFootText:{fontSize:10,color:'#e5ecdf'},card:{padding:15,borderWidth:0,borderRadius:0,backgroundColor:c.card,borderBottomWidth:1,borderBottomColor:c.line,marginTop:10},sectionTop:{flexDirection:'row',alignItems:'center',gap:10},sectionIcon:{width:38,height:38,borderRadius:0,alignItems:'center',justifyContent:'center',backgroundColor:c.cream},cardAction:{width:39,height:39,borderRadius:0,alignItems:'center',justifyContent:'center',backgroundColor:c.cream,borderWidth:1,borderColor:c.line},flex:{flex:1},sectionTitle:{fontSize:15,fontWeight:'900',color:c.ink},copy:{fontSize:11,lineHeight:17,color:c.muted,marginTop:3},copyStrong:{fontSize:12,lineHeight:18,color:c.ink,marginTop:13},statusPill:{paddingHorizontal:8,paddingVertical:5},statusGood:{},statusWait:{},statusText:{fontSize:9,fontWeight:'900',color:c.green},accountNumber:{marginTop:13,padding:13,borderRadius:0,backgroundColor:c.cream},accountLabel:{fontSize:9,fontWeight:'900',letterSpacing:1,color:c.muted},number:{fontSize:23,fontWeight:'900',letterSpacing:2,color:c.ink,marginTop:5},button:{marginTop:12},verifiedName:{fontSize:13,fontWeight:'800',color:c.ink,marginTop:12},selectBank:{minHeight:48,paddingHorizontal:13,borderWidth:1,borderColor:c.isDark?c.line:'#9aa99f',flexDirection:'row',alignItems:'center',justifyContent:'space-between',marginTop:14},selectBankValue:{fontSize:14,fontWeight:'700',color:c.ink},selectBankPlaceholder:{fontSize:14,color:c.muted},hint:{fontSize:11,color:c.muted,marginTop:8},historyHeading:{flexDirection:'row',alignItems:'center',justifyContent:'space-between',marginTop:23,marginBottom:5},historyCount:{fontSize:10,fontWeight:'800',color:c.muted},empty:{alignItems:'center',padding:22,borderRadius:0,backgroundColor:c.card,marginTop:9},emptyIcon:{width:42,height:42,borderRadius:0,backgroundColor:c.cream,alignItems:'center',justifyContent:'center'},emptyTitle:{fontSize:14,fontWeight:'900',color:c.ink,marginTop:10},transaction:{flexDirection:'row',alignItems:'center',gap:10,padding:12,borderRadius:0,borderWidth:0,borderBottomWidth:1,borderBottomColor:c.line,backgroundColor:c.card,marginTop:8},txIcon:{width:37,height:37,borderRadius:0,alignItems:'center',justifyContent:'center'},txIn:{},txOut:{},txCopy:{flex:1},txTitle:{fontSize:12,fontWeight:'900',color:c.ink},txStatus:{fontSize:9,fontWeight:'800',color:c.muted,marginTop:3},txAmount:{fontSize:12,fontWeight:'900',color:'#28865b'},txDebit:{color:c.ink},notice:{flexDirection:'row',alignItems:'center',justifyContent:'space-between',gap:8,padding:12,borderBottomWidth:1,borderBottomColor:c.line,marginBottom:10},noticeText:{flex:1,fontSize:11,lineHeight:16,color:c.green},errorBox:{padding:11,borderBottomWidth:1,borderBottomColor:'#f8e9e5',marginBottom:10},error:{fontSize:11,lineHeight:16,color:'#a44232'},modalBackdrop:{flex:1,justifyContent:'flex-end',backgroundColor:'rgba(0,0,0,.42)'},modal:{maxHeight:'78%',padding:18,paddingBottom:28,backgroundColor:c.paper},modalHead:{flexDirection:'row',alignItems:'center',justifyContent:'space-between',marginBottom:12},modalTitle:{fontSize:19,fontWeight:'900',color:c.ink},bankOption:{minHeight:48,flexDirection:'row',alignItems:'center',justifyContent:'space-between',borderBottomWidth:1,borderBottomColor:c.line,paddingVertical:9},bankName:{fontSize:13,fontWeight:'700',color:c.ink}});
